func Map_MappingDfs_rec(pNode *Map_Node_t, vNodes *Map_NodeVec_t, fCollectEquiv int32) {
    // inlining of macro Map_IsComplement
    assert(!(((int32(((ABC_PTRUINT_T) (pNode) & 01)) != 0))), "!/*__starting_point_inline_macro:Map_IsComplement__*/((int32(((ABC_PTRUINT_T) (pNode) & 01))))");
    if pNode.fMark0 {
        return; }
    // visit the transitive fanin
    if Map_NodeIsAnd(pNode) {
        // inlining of macro Map_Regular
        Map_MappingDfs_rec( ((Map_Node_t *)((ABC_PTRUINT_T)(pNode.p1) & ~01)) , vNodes, fCollectEquiv );
        // inlining of macro Map_Regular
        Map_MappingDfs_rec( ((Map_Node_t *)((ABC_PTRUINT_T)(pNode.p2) & ~01)) , vNodes, fCollectEquiv );
    }
    // visit the equivalent nodes
    if (fCollectEquiv != 0) && pNode.pNextE {
        Map_MappingDfs_rec( pNode.pNextE, vNodes, fCollectEquiv ); }
    // make sure the node is not visited through the equivalent nodes
    assert(pNode.fMark0 == 0, "pNode.fMark0 == 0");
    // mark the node as visited
    pNode.fMark0 = 1;
    // add the node to the list
    Map_NodeVecPush( vNodes, pNode );
}
