  Synopsis    [Unmarks the nodes.]

  Description []

  SideEffects []

  SeeAlso     []

***********************************************************************/
func Map_MappingUnmark(pMan *Map_Man_t) {
    var i int32;
    for  i = 0; i < pMan.nOutputs; i++  {
        // inlining of macro Map_Regular
        Map_MappingUnmark_rec( ((Map_Node_t *)((ABC_PTRUINT_T)(pMan.pOutputs[i]) & ~01))  );
    }
}

/**Function*************************************************************

  Synopsis    [Recursively unmarks the nodes.]

  Description []

  SideEffects []

  SeeAlso     []

***********************************************************************/
func Map_MappingUnmark_rec(pNode *Map_Node_t) {
    // inlining of macro Map_IsComplement
    assert(!(((int32(((ABC_PTRUINT_T) (pNode) & 01)) != 0))), "!/*__starting_point_inline_macro:Map_IsComplement__*/((int32(((ABC_PTRUINT_T) (pNode) & 01))))");
    if pNode.fMark0 == 0 {
        return; }
    pNode.fMark0 = 0;
    if !Map_NodeIsAnd(pNode) {
        return; }
    // inlining of macro Map_Regular
    Map_MappingUnmark_rec( ((Map_Node_t *)((ABC_PTRUINT_T)(pNode.p1) & ~01))  );
    // inlining of macro Map_Regular
    Map_MappingUnmark_rec( ((Map_Node_t *)((ABC_PTRUINT_T)(pNode.p2) & ~01))  );
    // visit the equivalent nodes
    if pNode.pNextE {
        Map_MappingUnmark_rec( pNode.pNextE ); }
}

/**Function*************************************************************

  Synopsis    []

  Description []

  SideEffects []

  SeeAlso     []

***********************************************************************/
func Map_MappingMark_rec(pNode *Map_Node_t) {
    // inlining of macro Map_IsComplement
    assert(!(((int32(((ABC_PTRUINT_T) (pNode) & 01)) != 0))), "!/*__starting_point_inline_macro:Map_IsComplement__*/((int32(((ABC_PTRUINT_T) (pNode) & 01))))");
    if pNode.fMark0 == 1 {
        return; }
    pNode.fMark0 = 1;
    if !Map_NodeIsAnd(pNode) {
        return; }
    // visit the transitive fanin of the selected cut
    // inlining of macro Map_Regular
    Map_MappingMark_rec( ((Map_Node_t *)((ABC_PTRUINT_T)(pNode.p1) & ~01))  );
    // inlining of macro Map_Regular
    Map_MappingMark_rec( ((Map_Node_t *)((ABC_PTRUINT_T)(pNode.p2) & ~01))  );
}

/**Function*************************************************************

  Synopsis    [Compares the outputs by their arrival times.]

  Description []

  SideEffects []

  SeeAlso     []

***********************************************************************/
func Map_MappingCompareOutputDelay(ppNode1 **Map_Node_t, ppNode2 **Map_Node_t) int32 {
    // inlining of macro Map_Regular
    var pNode1 *Map_Node_t  = ((Map_Node_t *)((ABC_PTRUINT_T)(*ppNode1) & ~01)) ;
    // inlining of macro Map_Regular
    var pNode2 *Map_Node_t  = ((Map_Node_t *)((ABC_PTRUINT_T)(*ppNode2) & ~01)) ;
    // inlining of macro Map_IsComplement
    var fPhase1 int32  = !((int32(((ABC_PTRUINT_T) (*ppNode1) & 01))));
    // inlining of macro Map_IsComplement
    var fPhase2 int32  = !((int32(((ABC_PTRUINT_T) (*ppNode2) & 01))));
    var Arrival1 float32  = pNode1.tArrival[fPhase1].Worst;
    var Arrival2 float32  = pNode2.tArrival[fPhase2].Worst;
    if Arrival1 < Arrival2 {
        return -1; }
    if Arrival1 > Arrival2 {
        return 1; }
    return 0;
}

/**Function*************************************************************

  Synopsis    [Finds given number of latest arriving COs.]

  Description []

  SideEffects []

  SeeAlso     []

***********************************************************************/
func Map_MappingFindLatest(p *Map_Man_t, pNodes *int32, nNodesMax int32) {
    var nNodes, i, k, v int32;
    assert(p.nOutputs >= nNodesMax, "p.nOutputs >= nNodesMax");
    pNodes[0] = 0;
    nNodes = 1;
    for  i = 1; i < p.nOutputs; i++  {
        for  k = nNodes - 1; k >= 0; k--  {
            if Map_MappingCompareOutputDelay( &p.pOutputs[pNodes[k]], &p.pOutputs[i] ) >= 0 {
                break; }
        }
        if k == nNodesMax - 1 {
            continue; }
        if nNodes < nNodesMax {
            nNodes++; }
        for  v = nNodes - 1; v > k+1; v--  {
            pNodes[v] = pNodes[v-1];
        }
        pNodes[k+1] = i;
    }
}

/**Function*************************************************************

  Synopsis    [Prints a bunch of latest arriving outputs.]

  Description []

  SideEffects []

  SeeAlso     []

***********************************************************************/
func Map_MappingPrintOutputArrivals(p *Map_Man_t) {
    var pSorted [MAP_CO_LIST_SIZE]int32;
    var pTimes *Map_Time_t;
    var pNode *Map_Node_t;
    var fPhase, Limit, i int32;
    var MaxNameSize int32;

    // determine the number of nodes to print
    if p.nOutputs > MAP_CO_LIST_SIZE {
        Limit = MAP_CO_LIST_SIZE;
    } else {
        Limit = p.nOutputs;
    }

    // determine the order
    Map_MappingFindLatest( p, pSorted, Limit );

    // determine max size of the node's name
    MaxNameSize = 0;
    for  i = 0; i < Limit; i++  {
        if MaxNameSize < int32(len(p.ppOutputNames[pSorted[i]])) {
            MaxNameSize = len(p.ppOutputNames[pSorted[i]]); }
    }

    // print the latest outputs
    for  i = 0; i < Limit; i++  {
        // get the i-th latest output
        // inlining of macro Map_Regular
        pNode  = ((Map_Node_t *)((ABC_PTRUINT_T)(p.pOutputs[pSorted[i]]) & ~01)) ;
        // inlining of macro Map_IsComplement
        fPhase =!((int32(((ABC_PTRUINT_T) (p.pOutputs[pSorted[i]]) & 01))));
        pTimes = pNode.tArrival + fPhase;
        // print out the best arrival time
        fmt.Printf("Output  %-*s : ", MaxNameSize + 3, p.ppOutputNames[pSorted[i]]);
        fmt.Printf("Delay = (%5.2f, %5.2f)  ", float64(pTimes.Rise), float64(pTimes.Fall));
        fmt.Printf("%s", fPhase? "POS" : "NEG");
        fmt.Printf("\n");
    }
}

/**Function*************************************************************

  Synopsis    [Sets up the truth tables.]

  Description []

  SideEffects []

  SeeAlso     []

***********************************************************************/
func Map_MappingSetupTruthTables(uTruths [][2]uint32) {
    var m, v int32;
    // set up the truth tables
    for  m = 0; m < 32; m++  {
        for  v = 0; v < 5; v++  {
            if m & (1 << v) {
                uTruths[v][0] |= (1 << m); }
        }
    }
    // make adjustments for the case of 6 variables
    for  v = 0; v < 5; v++  {
        uTruths[v][1] = uTruths[v][0];
    }
    uTruths[5][0] = 0;
    uTruths[5][1] = MAP_FULL;
}

/**Function*************************************************************

  Synopsis    [Sets up the truth tables.]

  Description []

  SideEffects []

  SeeAlso     []

***********************************************************************/
func Map_MappingSetupTruthTablesLarge(uTruths [][32]uint32) {
    var m, v int32;
    // clean everything
    for  m = 0; m < 32; m++  {
        for  v = 0; v < 10; v++  {
            uTruths[v][m] = 0;
        }
    }
    // set up the truth tables
    for  m = 0; m < 32; m++  {
        for  v = 0; v < 5; v++  {
            if m & (1 << v) {
                uTruths[v][0] |= (1 << m);
                uTruths[v+5][m] = MAP_FULL;
            }
        }
    }
    // extend this info for the rest of the first 5 variables
    for  m = 0; m < 32; m++  {
        for  v = 0; v < 5; v++  {
            uTruths[v][m] = uTruths[v][0];
        }
    }
