func Map_MappingCountUsedNodes(pMan *Map_Man_t, fChoices int32) int32 {
    var vNodes *Map_NodeVec_t;
    var Result int32;
    vNodes = Map_MappingDfs( pMan, fChoices );
    Result = vNodes.nSize;
    Map_NodeVecFree( vNodes );
    return Result;    
}

